edges = defaultdict(set)
for path in Path('blueprint/src/chapter').glob('*.tex'):
    text = re.sub(r'(?m)(?<"'!'"\\\\)%.*"'$'"', '', path.read_text())
    stack = []
    last = None
    token = r'\\\\(begin|end)\\{(lemma|theorem|definition|proposition|corollary|fact|remark|proof)\\}|\\\\(label|proves|uses)\\{(["'^}]+)'"\\}'
    for match in re.finditer(token, text):
        action, env, command, value = match.groups()
        if action == 'begin': stack.append([env, last if env == 'proof' else None, set()])
        elif action == 'end' and stack:
            frame = stack.pop()
            if frame[1]:
                edges[frame[1]].update(frame[2])
                if frame[0] "'!= '"'proof': last = frame[1]
        elif stack and command in ('label','proves'):
